"[prisma]": { "editor.defaultFormatter": "Prisma.prisma" },
// TypeScript 7 (Go-native) editor/CLI alignment — see .agents/skills/tech-stack/SKILL.md.
// Both SDK paths must resolve to the same devDependencies.typescript install (app/node_modules/typescript):
// - `typescript.tsdk`                -> the `/lib` dir      (language service)
// - `typescript.native-preview.tsdk` -> the package root
// Never point native-preview.tsdk at app/node_modules/@typescript/native-preview; that would make
// IDE diagnostics disagree with `bun run type-check`.
"js/ts.experimental.useTsgo": true,
"typescript.tsdk": "app/node_modules/typescript/lib",
"typescript.enablePromptUseWorkspaceTsdk": true,
"typescript.native-preview.tsdk": "app/node_modules/typescript",

